(function () {
  'use strict';
  const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const categories=[['account','My account'],['plan','My degree plan'],['course','A course or transfer option'],['bug','Something is not working'],['other','Something else']];
  let user=null,tickets=[],current=null,busy=false,dirty=false,restoreFocus=null,cursor=null,ticketsCursor=null,requestDraft={subject:'',category:'account',body:''};
  const author=message=>message.authorRole==='owner'?'DegreeSteps support':message.authorRole==='student'?'You':message.authorLabel||'Reply';
  const date=value=>{if(!value)return'Not recorded';const d=new Date(value);return Number.isNaN(d.valueOf())?'Not recorded':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});};
  function notice(message,error=false){const node=$(error?'help-error':'help-status');node.textContent=message||'';node.hidden=!message;}
  function field(name,label,type='text',value='',required=true){return'<label class="help-field"><span>'+esc(label)+'</span>'+(type==='textarea'?'<textarea name="'+name+'" rows="5" maxlength="6000"'+(required?' required':'')+'>'+esc(value)+'</textarea>':'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" maxlength="'+(name==='email'?'254':'180')+'"'+(required?' required':'')+'>')+'</label>';}
  async function api(path,{method='GET',body}={}){if(!/^\/api\/support\/[A-Za-z0-9_/?=&.%:-]+$/.test(path))throw Error('Invalid help action.');const headers={Accept:'application/json'};if(method!=='GET'){headers['Content-Type']='application/json';headers['X-Support-Request']='1';headers['X-Portal-Request']='1';}const response=await fetch(path,{method,headers,credentials:'same-origin',cache:'no-store',redirect:'error',...(method!=='GET'?{body:JSON.stringify(body||{})}:{})});let data;try{data=await response.json();}catch{data={};}if(!response.ok){const error=Error(typeof data.error==='string'?data.error:'Your help request could not be saved. Please try again.');error.status=response.status;throw error;}return data;}
  function signedOut(){return'<section class="help-panel"><h2>Sign in for help with your plan.</h2><p>Your signed-in help page keeps your requests and replies together.</p><a class="help-button" href="/account.html?returnTo=%2Fhelp.html">Sign in to get help</a><details class="help-login-fallback"><summary>Can’t sign in?</summary><p class="help-meta">You can save a sign-in help request using your email address. Include only what we need to understand the sign-in problem. Do not send passwords, security codes, transcripts, or private course records.</p><form id="help-login-form">'+field('email','Your account email','email')+field('body','What happens when you try to sign in?','textarea')+'<label class="help-honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="help-consent"><input name="contactConsent" type="checkbox" required><span>I want DegreeSteps to use this email address to help with my sign-in request.</span></label><p class="help-form-error" role="alert"></p><button class="help-button" type="submit">Save sign-in help request</button></form></details></section>';}
  function requestForm(){return'<section class="help-panel"><h2>Ask for help</h2><p>Describe the next step you’re trying to take. Your plan and private records stay separate from this request.</p><form id="help-request-form">'+field('subject','What do you need help with?','text',requestDraft.subject)+'<label class="help-field"><span>Topic</span><select name="category">'+categories.map(([v,l])=>'<option value="'+v+'"'+(requestDraft.category===v?' selected':'')+'>'+l+'</option>').join('')+'</select></label>'+field('body','Tell us what happened','textarea',requestDraft.body)+'<p class="help-meta">Please do not include passwords, security codes, Social Security numbers, or transcript files.</p><p class="help-form-error" role="alert"></p><button class="help-button" type="submit">Save help request</button></form></section>';}
  function render(){if(!user){$('help-workspace').innerHTML=signedOut();return;}$('help-workspace').innerHTML='<div class="help-layout">'+requestForm()+'<section class="help-panel"><h2>My help requests</h2><p>Open a request to read the saved reply or add details. Replies appear here; email is not sent automatically.</p>'+(tickets.length?tickets.map(item=>'<article class="help-ticket"><h3>'+esc(item.subject)+'</h3><p><span class="help-tag">'+esc(String(item.status||'open').replace(/-/g,' '))+'</span> · Updated '+esc(date(item.updatedAt||item.createdAt))+'</p><button type="button" class="help-button help-secondary" data-ticket="'+esc(item.id)+'">Open request</button></article>').join(''):'<p class="help-empty">You have no saved help requests yet.</p>')+'<div class="help-actions">'+(ticketsCursor?'<button type="button" class="help-button help-secondary" data-older-tickets>Show older requests</button>':'')+'<button type="button" class="help-button help-secondary" data-help-refresh>Refresh requests</button></div></section></div>';}
  async function load(){const session=await window.DegreeAccount.session(true);user=session.user;if(user){const data=await api('/api/support/tickets');tickets=Array.isArray(data.items)?data.items:[];ticketsCursor=data.nextCursor||null;}else tickets=[];render();}
  async function openTicket(id){const data=await api('/api/support/tickets/'+encodeURIComponent(id));current=data.item;cursor=data.messagesNextCursor||null;const messages=Array.isArray(data.messages)?data.messages:Array.isArray(current.messages)?current.messages:[];if(!$('help-dialog').open)restoreFocus=document.activeElement;$('help-dialog-body').innerHTML='<h2 id="help-dialog-title">'+esc(current.subject)+'</h2><p><span class="help-tag">'+esc(String(current.status).replace(/-/g,' '))+'</span></p><p class="help-private-body">'+esc(current.body||'')+'</p><div id="help-messages">'+messages.map(message=>'<article class="help-message"><p><strong>'+esc(author(message))+'</strong></p><p>'+esc(message.body)+'</p><small>'+esc(date(message.createdAt))+'</small></article>').join('')+'</div>'+(cursor?'<button class="help-button help-secondary" type="button" data-older-messages>Show older messages</button>':'')+'<form id="help-message-form">'+field('body','Add a reply','textarea')+'<p class="help-form-error" role="alert"></p><button class="help-button" type="submit">Save reply</button></form>';dirty=false;if(!$('help-dialog').open)$('help-dialog').showModal();}
  function closeDialog(){if(dirty){if(!$('help-unsaved-reply')){$('help-dialog-body').insertAdjacentHTML('beforeend','<div id="help-unsaved-reply" class="help-notice"><p>Your reply has not been saved. Keep editing, or close without saving it.</p><div class="help-actions"><button class="help-button" type="button" data-help-keep-editing>Keep editing</button><button class="help-button help-secondary" type="button" data-help-discard>Close without saving</button></div></div>');$('help-dialog-body').querySelector('[data-help-keep-editing]')?.focus();}return;}$('help-dialog').close();dirty=false;restoreFocus?.isConnected&&restoreFocus.focus();}
  document.addEventListener('input',event=>{if(event.target.closest('#help-message-form'))dirty=true;if(event.target.closest('#help-request-form')&&Object.hasOwn(requestDraft,event.target.name))requestDraft[event.target.name]=event.target.value;});
  document.addEventListener('change',event=>{if(event.target.closest('#help-request-form')&&Object.hasOwn(requestDraft,event.target.name))requestDraft[event.target.name]=event.target.value;});
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||busy)return;if(b.id==='help-dialog-close')return closeDialog();if(b.hasAttribute('data-help-keep-editing')){$('help-unsaved-reply')?.remove();$('help-message-form')?.querySelector('textarea')?.focus();return;}if(b.hasAttribute('data-help-discard')){dirty=false;return closeDialog();}if(b.hasAttribute('data-older-tickets')){busy=true;api('/api/support/tickets?cursor='+encodeURIComponent(ticketsCursor)).then(data=>{const known=new Set(tickets.map(item=>item.id));tickets=tickets.concat((data.items||[]).filter(item=>!known.has(item.id)));ticketsCursor=data.nextCursor||null;render();}).catch(e=>notice(e.message,true)).finally(()=>busy=false);return;}if(b.dataset.ticket){busy=true;openTicket(b.dataset.ticket).catch(e=>notice(e.message,true)).finally(()=>busy=false);}if(b.hasAttribute('data-help-refresh')){busy=true;load().catch(e=>notice(e.message,true)).finally(()=>busy=false);}if(b.hasAttribute('data-older-messages')&&current){busy=true;api('/api/support/tickets/'+encodeURIComponent(current.id)+'?cursor='+encodeURIComponent(cursor)).then(data=>{const container=$('help-messages'),html=(data.messages||[]).map(message=>'<article class="help-message"><p><strong>'+esc(author(message))+'</strong></p><p>'+esc(message.body)+'</p><small>'+esc(date(message.createdAt))+'</small></article>').join('');container.insertAdjacentHTML('afterbegin',html);cursor=data.messagesNextCursor||null;b.hidden=!cursor;}).catch(e=>notice(e.message,true)).finally(()=>busy=false);}});
  document.addEventListener('submit',event=>{const form=event.target;if(!['help-login-form','help-request-form','help-message-form'].includes(form.id))return;event.preventDefault();if(busy)return;busy=true;const data=new FormData(form),button=event.submitter;if(button)button.disabled=true;const alert=form.querySelector('.help-form-error');alert.textContent='';(async()=>{try{if(form.id==='help-login-form'){if(!data.has('contactConsent'))throw Error('Confirm that you want help using this email address.');const body={email:data.get('email'),subject:'Sign-in help',category:'account',body:data.get('body'),contactConsent:true,website:data.get('website')||''};if(new TextEncoder().encode(JSON.stringify(body)).byteLength>4096)throw Error('Shorten your sign-in help request so it fits within 4 KB. Your text has not been removed.');const result=await api('/api/support/login-help',{method:'POST',body});form.reset();notice('Your sign-in help request was saved. Keep this receipt: '+(result.receiptId||'saved')+'. This form does not send email automatically.');}if(form.id==='help-request-form'){await api('/api/support/tickets',{method:'POST',body:{subject:data.get('subject'),category:data.get('category'),body:data.get('body')}});requestDraft={subject:'',category:'account',body:''};await load();notice('Your help request is saved. Return here to read a reply.');}if(form.id==='help-message-form'){await api('/api/support/tickets/'+encodeURIComponent(current.id)+'/messages',{method:'POST',body:{revision:current.revision,body:data.get('body')}});dirty=false;await openTicket(current.id);notice('Your reply was saved.');}}catch(error){alert.textContent=error.message+(error.status===409?' Refresh the request before adding another reply.':'');}finally{busy=false;if(button?.isConnected)button.disabled=false;}})();});
  $('help-dialog').addEventListener('cancel',event=>{if(dirty){event.preventDefault();closeDialog();}});
  window.addEventListener('beforeunload',event=>{if(dirty||requestDraft.subject||requestDraft.body){event.preventDefault();event.returnValue='';}});
  load().catch(error=>{notice(error.message,true);$('help-workspace').innerHTML=signedOut();});
}());
